from common import *
import dg

def build():
    h = [part("p2", 2, "Tools, Timber &amp; Salvage")]
    h.append(h2("tools", "2.1 Hand tools"))
    h.append('<p>A house can be built with no electricity at all — every log cabin, timber frame and adobe on the continent was, until about 1900. Buy or salvage good steel tools now, along with files and stones to keep them sharp; a dull tool is slow and dangerous. Old American and Canadian tools from estate sales are often better steel than cheap new ones.</p>')
    h.append(table(["Job", "Core tools", "Nice to have"], [
        ["Felling & bucking", "Felling axe (3–3.5 lb head), bow saw, two-man crosscut saw (5–6 ft), wedges (plastic/aluminum for saws, steel for splitting), sledge", "Chainsaw + fuel, bar oil, chain files, PPE (see 2.2); peavey or cant hook; log tongs"],
        ["Hewing & shaping", "Broadaxe or side axe, adze, drawknife, spud/bark peeler, chalk line, plumb bob, carpenter's square", "Log dogs, timber framer's slick, scorp, hewing hatchet"],
        ["Joinery", "Hand saws (rip + crosscut), chisels (½–2 in), mallet, brace + auger bits (½–1½ in), framing square, marking gauge", "Boring machine, timber-frame chisels (1½–2 in), scribers (for log scribing)"],
        ["Framing & finishing", "Claw hammer, nail bar/crowbar, block plane, jack plane, tape, 4 ft level, string, utility knife, tin snips", "Hand drill, saw set, sharpening stones, bench vise, sawhorses, ladders, come-along"],
        ["Earth & masonry", "Round and square shovels, mattock, pickaxe, wheelbarrow, buckets, tampers, trowels, mortar box, hoe", "Screen for soil/sand, adobe/brick molds, rammed-earth forms (see Concrete & Masonry vol.)"],
        ["Shakes & roofing", "Froe and club (mallet), shaving horse, drawknife, roofing hammer/hatchet", "Shingle horse, snips, seaming tools for metal"],
        ["Measuring & layout", "100 ft tape, line level or water level (clear hose filled with water), stakes, string, 3-4-5 triangle", "Transit or builder's level, compass, inclinometer"]]))
    h.append(tip("Square a building with 3-4-5", "Any triangle with sides 3, 4 and 5 units has a perfect right angle. For a foundation, measure 6 ft along one string and 8 ft along the other from the corner; adjust until the diagonal between those marks is exactly 10 ft (or 3/4/5 m). Then check the finished rectangle: both diagonals must be equal. A <b>water level</b> (clear hose with no bubbles) gives level points accurate to a few millimeters over 30 m, around corners, with no batteries."))

    h.append(h2("felling", "2.2 Felling and working timber"))
    h.append(danger("Felling is one of the most dangerous jobs there is", "Logging has one of the highest fatality rates of any occupation (OSHA). Never fell alone; never fell in strong wind; clear brush around the trunk and plan <b>two escape routes</b>; watch for dead limbs overhead; never work under a hung-up tree — pull it down with a rope and come-along from a distance. With a chainsaw wear a helmet with face screen, hearing protection, chaps, gloves and boots. Bucking on slopes: always stand uphill of the log."))
    h.append(fig(dg.felling(), "Directional felling. Cut the notch on the side facing the fall, ¼–⅓ of the way through; make the back cut level with or slightly above the notch floor, leaving a hinge about 10% of the diameter that steers the tree. Retreat along an escape route as soon as the tree starts to move.", "max-width:62%"))
    h.append(table(["Use", "Good species (N. America)", "Notes"], [
        ["Wall logs", "Lodgepole, white, red & ponderosa pine; spruce; Douglas-fir; western red & northern white cedar; tamarack/larch; aspen/poplar (only if kept dry)", "Straight, little taper, 8–14 in (20–35 cm) diameter; cut 1–2 ft long for trimming"],
        ["Sills, posts, ground contact", "Heartwood of black locust, Osage orange, white oak, eastern red cedar, western red cedar, redwood, bald cypress, catalpa, mulberry; larch", "No wood is rot-proof in wet soil — keep it on stone or 8 in (20 cm) above grade"],
        ["Timber frame & beams", "Oak, Douglas-fir, eastern white pine, hemlock, spruce, larch", "Hewn or sawn square; work oak green — it is far easier"],
        ["Shakes & shingles", "Western red cedar, northern white cedar, white oak, chestnut (salvage), cypress, redwood", "Straight-grained, knot-free butts; rive with a froe"],
        ["Avoid for structure", "Soft maple, basswood, cottonwood, willow, birch in ground contact", "Rot quickly; use for interior, furniture, fuel"]]))
    h.append('<ul><li><b>When to cut:</b> late fall and winter — less sap, fewer insects, slower stain and rot, logs skid easily on snow.</li>'
             '<li><b>Peel promptly:</b> remove bark within weeks (it peels easiest in spring/early summer). Bark harbors beetles and traps moisture. Stack peeled logs off the ground on cross-skids, covered on top.</li>'
             '<li><b>Drying:</b> air-dry sawn lumber stacked flat with sticks (“stickers”) every 2 ft, top covered, sides open; roughly <b>one year per inch of thickness</b> for hardwoods (less for softwoods). Logs and green timber frames are traditionally built green and allowed to dry in place — plan for shrinkage.</li>'
             '<li><b>Shrinkage:</b> wood shrinks very little along its length but several percent across the grain as it dries (USDA Wood Handbook). A green log wall settles — commonly several inches on an 8 ft wall — so leave settling space above doors and windows (see Part 4).</li>'
             '<li><b>Hewing:</b> snap chalk lines on both sides of the log, “score” cuts every 4–6 in with a felling axe down to the line, knock off the chunks (“juggling”), then smooth to the line with a broadaxe.</li>'
             '<li><b>Splitting boards:</b> straight-grained logs can be split into planks with wedges and a froe (riving); this was how fences, shakes and floor puncheons were made before sawmills.</li></ul>')

    h.append(h2("salvage", "2.3 Salvaging materials safely"))
    h.append('<p>Abandoned buildings hold enormous value: framing lumber, metal roofing, windows, doors, hardware, nails and screws, wire, pipe, insulation, brick and stone. Take buildings apart in the <b>reverse</b> of the order they were built — roofing, then sheathing, rafters, walls, floors — and never pull out a support while something is resting on it.</p>')
    h.append(danger("Asbestos — do not break it, do not breathe it", "Many North American buildings from before about 1980 contain asbestos (EPA). Inhaled fibers cause asbestosis, lung cancer and mesothelioma decades later; there is no treatment. <b>Assume it is present</b> in: vermiculite attic insulation (grey-brown pebbles), pipe and boiler insulation, 9×9 in floor tiles and black mastic, popcorn ceilings, textured plaster and joint compound, cement siding and roof shingles (“transite”), roofing felts, window putty, duct wrap. Intact material left in place is low risk. If you must move it: wet it thoroughly first, do not saw, sand, drill or break it, wear a <b>P100 / HEPA respirator</b> (paper dust masks and plain N95s are not adequate), disposable coveralls, and bag it wet. Best of all, salvage elsewhere."))
    h.append(danger("Lead paint", "Homes built before 1978 probably contain lead paint (CDC). Lead dust damages the brain and nerves, especially in children and pregnant women; there is no safe blood level. Do <b>not</b> dry-sand, power-plane, heat-gun or burn painted wood. Use EPA lead-safe practices: mist with water and hand-scrape, contain debris on plastic sheeting, wear a P100 respirator, wash hands and face before eating, keep children away, and clean with wet wipes and a HEPA vacuum — never dry-sweep. Plane or saw old painted boards only outdoors, wet, or remove the painted surface first. <b>Never burn</b> painted wood or pressure-treated lumber (older treated wood contains arsenic — CCA)."))
    h.append(danger("Structural collapse and other hazards", "Do not enter buildings with sagging roof lines, leaning or cracked walls, fire damage, flood-soaked floors, or after an earthquake until you have shored them. Never work alone; keep someone outside who knows where you are. Wear a hard hat, boots with stiff soles (nails), gloves and eye protection; keep tetanus vaccination current. Watch for gas (propane tanks, buried lines), live wires if any power remains, rotten floors over basements, wasp and animal nests. <b>Rodent droppings:</b> hantavirus is spread in the dust — air the building out, soak droppings with a bleach solution, wipe up, and never sweep or vacuum them dry (CDC). Mold: wear a respirator; discard soaked insulation and drywall."))
    h.append(table(["Material", "Salvage value", "Watch out for"], [
        ["Framing lumber (2×4–2×12)", "Excellent; old-growth pre-1950 lumber is often stronger than modern", "Nails (pull or cut off), rot at bottoms and around leaks, insect damage, lead paint"],
        ["Metal roofing & siding", "Excellent — light, fast, fireproof, good for rain catchment", "Rust-through, sharp edges; old nail holes (seal with gasketed screws)"],
        ["Windows & glass", "Very high — glass is nearly impossible to make by hand", "Glazing putty and paint may contain asbestos and lead; carry panes vertically, wear gloves"],
        ["Doors & hardware", "High — solid doors, hinges, locks, bolts, screws, nails", "Lead paint on old doors"],
        ["Brick & stone", "High for foundations, chimneys, thermal mass", "Old soft lime mortar is easy to clean; cement mortar is not. Chimney bricks may hold creosote"],
        ["Insulation", "Fiberglass, mineral wool and rigid foam boards are worth taking if clean and dry", "Vermiculite (asbestos risk — leave it); wet or rodent-soiled insulation"],
        ["Plywood/OSB", "Good if dry", "Delamination from water; swollen edges"],
        ["Plumbing, wire, tanks", "Pipe for water lines, wire, water heaters (make cisterns), barrels", "Lead pipe and solder in old systems (not for drinking water)"]]))
    return "\n".join(h)
